parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const subject = item.json.subject || 'Untitled Task';
  const body = item.json.snippet || item.json.textPlain || '';
  const from = item.json.from?.value?.[0]?.address || item.json.from || 'Unknown';
  const date = item.json.date || new Date().toISOString();

  // Extract priority from subject
  let priority = 'Medium';
  const subjectLower = subject.toLowerCase();
  if (subjectLower.includes('[urgent]') || subjectLower.includes('[high]')) priority = 'High';
  if (subjectLower.includes('[low]')) priority = 'Low';

  // Clean subject
  const cleanSubject = subject.replace(/\[(urgent|high|low|task)\]/gi, '').trim();

  return {
    json: {
      taskName: cleanSubject,
      description: body.substring(0, 2000),
      sender: from,
      receivedDate: date,
      priority: priority,
      originalSubject: subject
    }
  };
});

